<template>
    <div>
        <el-dialog title="绑定Token" :visible.sync="show" width="500px">
            <el-tabs v-model="mode" type="card">
                <el-tab-pane label="直接填令牌" name="raw">
                    <el-form :model="tokenForm" ref="tokenForm" label-width="100px">
                        <el-form-item label="GitHub">
                            <el-tag>{{githubUsername}}</el-tag>
                        </el-form-item>
                        <el-form-item prop="token" label="Token" :rules="[{ required: true, message: '请输入accessToken', trigger: 'blur' }]">
                            <el-input v-model="tokenForm.token" placeholder="请保管好Token"></el-input>
                        </el-form-item>
                    </el-form>
                </el-tab-pane>

                <el-tab-pane label="密码解锁" name="vault">
                    <el-alert type="info" :closable="false" style="margin-bottom:10px"
                        title="用桌面密文 + 自定义密码，在浏览器本地还原令牌（令牌不落盘）"></el-alert>
                    <el-form :model="vaultForm" ref="vaultForm" label-width="100px">
                        <el-form-item label="GitHub">
                            <el-tag>{{githubUsername}}</el-tag>
                        </el-form-item>
                        <el-form-item label="密文" prop="cipher" :rules="[{ required: true, message: '粘贴桌面 .txt 里的密文', trigger: 'blur' }]">
                            <el-input type="textarea" :rows="3" v-model="vaultForm.cipher" placeholder="v1:...."></el-input>
                        </el-form-item>
                        <el-form-item label="密码" prop="password" :rules="[{ required: true, message: '请输入自定义密码', trigger: 'blur' }]">
                            <el-input type="password" v-model="vaultForm.password" placeholder="自定义密码"></el-input>
                        </el-form-item>
                    </el-form>
                </el-tab-pane>
            </el-tabs>

            <span slot="footer" class="dialog-footer">
                <el-button @click="show = false">取 消</el-button>
                <el-button type="primary" @click="onSubmit" :loading="loading">确 定</el-button>
            </span>
        </el-dialog>
    </div>
</template>

<script>
    import { mapGetters } from 'vuex'
    import vault from '@/utils/vault'
    export default {
        data() {
            return {
                show: false,
                mode: 'raw',
                loading: false,
                handleClose: null,
                tokenForm: {
                    token: ""
                },
                vaultForm: {
                    cipher: "",
                    password: ""
                }
            }
        },
        computed: {
            ...mapGetters([
                'githubUsername'
            ])
        },
        methods: {
            open(handleClose) {
                this.handleClose = handleClose
                this.mode = 'raw'
                this.tokenForm.token = ""
                this.vaultForm.cipher = ""
                this.vaultForm.password = ""
                this.show = true
            },
            onSubmit() {
                if (this.mode === 'raw') {
                    this.$refs["tokenForm"].validate((valid) => {
                        if (valid) {
                            this.$store.dispatch("Authentication", this.tokenForm.token)
                            if (typeof this.handleClose == "function") this.handleClose()
                            this.show = false
                        }
                    })
                    return
                }
                // 密码解锁模式
                this.$refs["vaultForm"].validate(async (valid) => {
                    if (!valid) return
                    this.loading = true
                    try {
                        const token = await vault.openToken(this.vaultForm.cipher.trim(), this.vaultForm.password)
                        this.$store.dispatch("Authentication", token)
                        if (typeof this.handleClose == "function") this.handleClose()
                        this.show = false
                    } catch (e) {
                        this.$message({ message: e.message || '解锁失败', type: 'error' })
                    } finally {
                        this.loading = false
                    }
                })
            }
        }
    }
</script>


